package net.civeira.phylax.features.access.userprofile.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.userprofile.domain.UserProfile;
import net.civeira.phylax.features.access.userprofile.domain.event.UserProfileEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserProfileEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserProfileEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserProfile entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
